        ('/**\n     * Returns bytes amount used by object in Redis memory. \n     * \n     * @return size in bytes\n     */', '/**\n     * 返回该对象在 Redis 内存中占用的字节数。 \n     * \n     * @return 内存占用字节数\n     */'),
        ('/**\n     * Restores object using its state returned by {@link #dumpAsync()} method.\n     * \n     * @param state - state of object\n     * @return void\n     */', '/**\n     * 使用 {@link #dumpAsync()} 返回的状态快照恢复对象。\n     * \n     * @param state 对象状态快照\n     * @return 无返回值\n     */'),
        ('/**\n     * Restores object using its state returned by {@link #dumpAsync()} method and set time to live for it.\n     * \n     * @param state - state of object\n     * @param timeToLive - time to live of the object\n     * @param timeUnit - time unit\n     * @return void\n     */', '/**\n     * 使用 {@link #dumpAsync()} 返回的状态恢复对象，并设置存活时间（TTL）。\n     * \n     * @param state 对象状态快照\n     * @param timeToLive 存活时间\n     * @param timeUnit 时间单位\n     * @return 无返回值\n     */'),
        ('/**\n     * Restores and replaces object if it already exists.\n     * \n     * @param state - state of the object\n     * @return void\n     */', '/**\n     * 恢复对象；若键已存在则覆盖替换。\n     * \n     * @param state 对象状态快照\n     * @return 无返回值\n     */'),
