        ('/**\n     * Returns dump of object\n     * \n     * @return dump\n     */', '/**\n     * 返回对象的序列化快照（DUMP 格式）\n     * \n     * @return 序列化快照字节数组\n     */'),
        ('/**\n     * Update the last access time of an object in async mode. \n     * \n     * @return <code>true</code> if object was touched else <code>false</code>\n     */', '/**\n     * 异步更新对象的最后访问时间。 \n     * \n     * @return 成功更新访问时间则为 true，否则 false\n     */'),
        ('/**\n     * Transfer object from source Redis instance to destination Redis instance\n     * in async mode\n     *\n     * @param host - destination host\n     * @param port - destination port\n     * @param database - destination database\n     * @param timeout - maximum idle time in any moment of the communication with the destination instance in milliseconds\n     * @return void\n     */', '/**\n     * 异步将对象从源 Redis 实例迁移到目标实例\n     *\n     * @param host 目标主机\n     * @param port 目标端口\n     * @param database 目标数据库编号\n     * @param timeout 与目标实例通信的最大空闲时间（毫秒）\n     * @return 无返回值\n     */'),
        ('/**\n     * Copy object from source Redis instance to destination Redis instance\n     * in async mode\n     *\n     * @param host - destination host\n     * @param port - destination port\n     * @param database - destination database\n     * @param timeout - maximum idle time in any moment of the communication with the destination instance in milliseconds\n     * @return void\n     */', '/**\n     * 将对象从源 Redis 实例复制到目标 Redis 实例\n     * in async mode\n     *\n     * @param host 目标主机\n     * @param port 目标端口\n     * @param database 目标数据库编号\n     * @param timeout 与目标实例通信的最大空闲时间（毫秒）\n     * @return 无返回值\n     */'),
