        ('/**\n     * Delete object in async mode\n     *\n     * @return <code>true</code> if object was deleted <code>false</code> if not\n     */', '/**\n     * 异步删除对象\n     *\n     * @return <code>true</code> if object was deleted <code>false</code> if not\n     */'),
